<?php declare(strict_types=1); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arquivos — ZystemWorkSpace</title><style>:root{font:15px system-ui;color:#e8eef7;background:#080d14}body{margin:0;padding:28px;max-width:1120px}main{max-width:1120px;margin:auto}.hero,.toolbar,.panel{background:linear-gradient(145deg,#101a28,#0d1622);border:1px solid #263b56;border-radius:16px;padding:18px;margin-bottom:14px;box-shadow:0 16px 40px #0002}.hero{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.hero h1{margin:0 0 6px}.muted{color:#91a5bd;line-height:1.5}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.toolbar input{flex:1;min-width:230px}button,input,textarea{font:inherit;border:1px solid #385474;border-radius:8px;background:#0b1420;color:#e8eef7;padding:10px}button{cursor:pointer;background:#193b5d}button:hover{background:#25527c}.danger{background:#642b36}.usage{min-width:230px;border:1px solid #263b56;padding:12px;border-radius:11px;font-size:12px;color:#9eb1c7}.usage b{display:block;color:#fff}.usage-bar,.progress{height:7px;background:#18283b;border-radius:99px;overflow:hidden;margin-top:7px}.usage-bar i,.progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6da7ff,#8ee0ad)}.table{overflow:auto;border:1px solid #263b56;border-radius:12px}.row{display:grid;grid-template-columns:minmax(240px,1fr) 100px 100px minmax(270px,auto);gap:10px;padding:12px 14px;border-bottom:1px solid #203148;align-items:center;min-width:760px}.row:hover{background:#142238}.name{color:#b9d7ff;cursor:pointer}.actions{display:flex;gap:5px;flex-wrap:wrap}.editor{display:grid;gap:10px}.editor textarea{min-height:300px;width:100%;font-family:ui-monospace,monospace}.hidden{display:none}.status{min-height:24px;color:#9fe0b0}.error{color:#ff9d9d}.preview{max-width:100%;max-height:480px}@media(max-width:700px){body{padding:18px}.hero{display:block}.usage{margin-top:14px}}
</style></head><body><?php require __DIR__ . '/menu.php'; ?><main><div class="hero"><div><h1>Arquivos</h1><div class="muted">Organize, edite, visualize e envie arquivos da sua workspace.</div></div><div class="usage" id="usage"><b>Uso do workspace</b><span>Calculando…</span><div class="usage-bar"><i></i></div></div></div><section class="toolbar"><input id="path" value="arquivos" aria-label="Pasta atual"><button id="refresh">Atualizar</button><button id="up">Subir</button><button id="mkdir">Nova pasta</button><button id="newfile">Novo arquivo</button><form id="uploadForm"><input id="upload" type="file" required><button>Enviar</button></form></section><div class="progress" id="uploadProgress"><i></i></div><div class="status" id="status" aria-live="polite"></div><section class="panel table" id="list">Carregando...</section><section class="panel editor hidden" id="editor"><strong id="editorTitle">Editor</strong><input id="editorPath"><textarea id="editorContent"></textarea><div><button id="save">Salvar</button><button id="cancel">Cancelar</button></div></section><section class="panel editor hidden" id="viewer"><strong id="viewerTitle">Preview</strong><div id="viewerBody"></div></section></main><script>const $=s=>document.querySelector(s),path=$('#path'),list=$('#list'),status=$('#status'),editor=$('#editor'),ep=$('#editorPath'),ec=$('#editorContent'),viewer=$('#viewer'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current='arquivos';function msg(x,err=false){status.textContent=x;status.className='status'+(err?' error':'')}function join(a,b){return(a==='.'?'':a.replace(/\/$/,'')+'/')+b}async function api(url,opts){const r=await fetch(url,opts),t=await r.text();let d;try{d=JSON.parse(t)}catch(e){throw Error('Resposta inválida do servidor: '+t.slice(0,120))}if(!d.ok)throw Error(d.error||'Falha');return d}async function usage(){try{const d=await api('../api/usage.php');const el=$('#usage');el.querySelector('span').textContent=`${d.files} arquivos · ${d.human_size} de ${d.human_limit}`;el.querySelector('i').style.width=d.percent+'%'}catch(e){}}async function load(p=current){try{current=p||'arquivos';path.value=current;const d=await api('../api/files.php?path='+encodeURIComponent(current));list.innerHTML='<div class="row"><b>Nome</b><b>Tipo</b><b>Tamanho</b><b>Ações</b></div>'+(d.items||[]).map(x=>{const q=join(current,x.name);return `<div class="row"><span class="name" data-open="${encodeURIComponent(q)}">${x.type==='directory'?'📁':'📄'} ${esc(x.name)}</span><span>${esc(x.type)}</span><span>${x.size==null?'—':x.size+' B'}</span><span class="actions"><button data-action="open" data-path="${encodeURIComponent(q)}">Abrir</button>${x.type==='file'?`<button data-action="edit" data-path="${encodeURIComponent(q)}">Editar</button><button data-action="preview" data-path="${encodeURIComponent(q)}">Preview</button><button data-action="download" data-path="${encodeURIComponent(q)}">Baixar</button>`:''}<button data-action="rename" data-path="${encodeURIComponent(q)}">Renomear</button><button data-action="delete" class="danger" data-path="${encodeURIComponent(q)}">Excluir</button></span></div>`}).join('')||'<div class="row">Pasta vazia.</div>';msg(`${(d.items||[]).length} item(ns)`);usage()}catch(e){msg(e.message,true)}}async function edit(p){try{const d=await api('../api/files.php?action=read&path='+encodeURIComponent(p));ep.value=p;ec.value=d.content;editor.classList.remove('hidden');viewer.classList.add('hidden')}catch(e){msg(e.message,true)}}async function save(){try{let d=await api('../api/file_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',path:ep.value,content:ec.value,confirmed:false})});if(d.result?.requer_confirmacao&&!confirm('O arquivo já existe. Substituir e criar backup?'))return;if(d.result?.requer_confirmacao)d=await api('../api/file_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',path:ep.value,content:ec.value,confirmed:true})});msg('Arquivo salvo.');load(current)}catch(e){msg(e.message,true)}}async function action(a,p,extra={}){try{if(a==='download'){location.href='../api/files.php?action=download&path='+encodeURIComponent(p);return}if(a==='open'){const d=await api('../api/files.php?path='+encodeURIComponent(p));if(d.items)load(p);else edit(p);return}if(a==='edit'){edit(p);return}if(a==='preview'){viewer.classList.remove('hidden');$('#viewerTitle').textContent=p;$('#viewerBody').innerHTML=`<iframe class="preview" style="width:100%;height:480px" src="../api/file_preview.php?path=${encodeURIComponent(p)}"></iframe>`;return}if(a==='rename'){const n=prompt('Novo nome:',p.split('/').pop());if(!n)return;extra.destination=n}if(a==='delete'&&!confirm('Enviar este arquivo para a lixeira?'))return;await api('../api/file_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:a,path:p,...extra,confirmed:a==='delete'})});msg('Operação concluída.');load(current)}catch(e){msg(e.message,true)}}list.onclick=e=>{const b=e.target.closest('[data-action]'),n=e.target.closest('[data-open]');if(b)action(b.dataset.action,decodeURIComponent(b.dataset.path));else if(n)action('open',decodeURIComponent(n.dataset.open))};$('#refresh').onclick=()=>load(current);$('#up').onclick=()=>load(current.includes('/')?current.split('/').slice(0,-1).join('/')||'arquivos':'arquivos');$('#mkdir').onclick=async()=>{const n=prompt('Nome da pasta:');if(n)action('mkdir',join(current,n))};$('#newfile').onclick=()=>{editor.classList.remove('hidden');viewer.classList.add('hidden');ep.value=join(current,'novo.txt');ec.value=''};$('#save').onclick=save;$('#cancel').onclick=()=>editor.classList.add('hidden');$('#uploadForm').onsubmit=e=>{e.preventDefault();const file=$('#upload').files[0],bar=$('#uploadProgress'),fill=bar.querySelector('i');if(!file)return msg('Escolha um arquivo.',true);const xhr=new XMLHttpRequest();xhr.open('POST','../api/upload.php');xhr.upload.onprogress=e=>{bar.style.display='block';if(e.lengthComputable){fill.style.width=(e.loaded/e.total*100)+'%';msg('Enviando… '+Math.round(e.loaded/e.total*100)+'%')}};xhr.onload=()=>{try{const d=JSON.parse(xhr.responseText);if(!d.ok)throw Error(d.error||'Upload recusado');msg('Upload concluído.');e.target.reset();load(current)}catch(x){msg(x.message,true)}finally{setTimeout(()=>{bar.style.display='none';fill.style.width='0'},800)}};xhr.onerror=()=>msg('Falha de rede durante o upload.',true);const data=new FormData();data.append('path',current);data.append('file',file);bar.style.display='block';xhr.send(data)};load();</script></body></html>
